import { request, requestOrNull, seg, Page, requestFile, ExportRequest } from './apiSupport';
import { LeadDTO } from './LeadDTO';
import { LeadKeyDTO } from './LeadKeyDTO';
import { LeadSrchDTO } from './LeadSrchDTO';
import { LeadStatus } from './LeadStatus';

/**
 * REST client for Lead.
 *
 * Calls the endpoints LeadController exposes. Generated from the same model the
 * server is, so a change to the DSL shows up here as a type error rather than
 * at runtime.
 *
 * Generated by ElastiCORE. Do not edit outside the ElastiCORE guidelines.
 */
const BASE = '/api/crm/lead';

/** Registers a new Lead. */
export async function create(input: LeadDTO, init?: RequestInit): Promise<LeadDTO> {
    return request<LeadDTO>('POST', BASE, input, init);
}

/** The Lead with this identifier, or null when there is none. */
export async function findById(leadId: number, init?: RequestInit): Promise<LeadDTO | null> {
    return requestOrNull<LeadDTO>('GET', BASE + '/' + seg(leadId), init);
}

/** Every Lead matching the condition. */
export async function search(condition: LeadSrchDTO, init?: RequestInit): Promise<Page<LeadDTO>> {
    return request<Page<LeadDTO>>('POST', BASE + '/search', condition, init);
}

/** Updates an existing Lead. */
export async function update(input: LeadDTO, init?: RequestInit): Promise<LeadDTO> {
    return request<LeadDTO>('PUT', BASE, input, init);
}

/** Updates several in one transaction; none are applied if any fails. */
export async function batchUpdate(inputs: LeadDTO[], init?: RequestInit): Promise<void> {
    return request<void>('PUT', BASE + '/batch', inputs, init);
}

/** Deletes each key, answering for each whether it was there. */
export async function deleteMany(keys: LeadKeyDTO[], init?: RequestInit): Promise<boolean[]> {
    return request<boolean[]>('POST', BASE + '/delete', keys, init);
}

/** Deletes the Lead with this identifier. */
export async function deleteById(leadId: number, init?: RequestInit): Promise<boolean> {
    return request<boolean>('DELETE', BASE + '/' + seg(leadId), undefined, init);
}

/** The rows the search finds as a file: CSV, or an .xlsx workbook (format: 'xlsx'). */
export async function exportLead(body: ExportRequest<LeadSrchDTO>, init?: RequestInit): Promise<Blob> {
    return requestFile('POST', BASE + '/export', body, init);
}

/** Whether qualify may be given now: the status is NEW. */
export function canQualify(value: LeadDTO | null | undefined): boolean {
    return value != null && (value.status === LeadStatus.NEW);
}

/** Whether convert may be given now: the status is QUALIFIED. */
export function canConvert(value: LeadDTO | null | undefined): boolean {
    return value != null && (value.status === LeadStatus.QUALIFIED);
}

/** Whether disqualify may be given now: the status is NEW or QUALIFIED. */
export function canDisqualify(value: LeadDTO | null | undefined): boolean {
    return value != null && (value.status === LeadStatus.NEW || value.status === LeadStatus.QUALIFIED);
}

/** Whether it may be deleted now: the status is NEW or LOST. */
export function canDelete(value: LeadDTO | null | undefined): boolean {
    return value != null && (value.status === LeadStatus.NEW || value.status === LeadStatus.LOST);
}

/** The qualify command: Lead decides, and answers with what it became. */
export async function qualify(leadId: number, init?: RequestInit): Promise<LeadDTO> {
    return request<LeadDTO>('POST', BASE + '/' + seg(leadId) + '/qualify', undefined, init);
}

/** The convert command: Lead decides, and answers with what it became. */
export async function convert(leadId: number, init?: RequestInit): Promise<LeadDTO> {
    return request<LeadDTO>('POST', BASE + '/' + seg(leadId) + '/convert', undefined, init);
}

/** The disqualify command: Lead decides, and answers with what it became. */
export async function disqualify(leadId: number, init?: RequestInit): Promise<LeadDTO> {
    return request<LeadDTO>('POST', BASE + '/' + seg(leadId) + '/disqualify', undefined, init);
}

